# Test variant: ArrowIpcIntegrationTest against a live server. Source of
# truth for test-arrow-ipc in .github/workflows/weekly.yml.

export PARENT_CONFIG=gpu-release
export RUNNER=server

export BINARY="Tests/ArrowIpcIntegrationTest"

# QueryRenderer must be compiled before ArrowIpcIntegrationTest because
# Execute.cpp includes AutoGeneratedShaders.h (generated into the build tree
# under QueryRenderer/). Building QueryRenderer first ensures the header
# exists and the include path is on the compiler's search list.
export MAKE_TARGETS="QueryRenderer ArrowIpcIntegrationTest"
